PHP_QT_API void {!! $ctx->wrapNativeFunc !!}(zval *return_value, {!! $ctx->nativeCppType !!} *native,
    zend_class_entry *ce, bool prevent_destroy)
{
    if (!native) {
        ZVAL_NULL(return_value);
        return;
    }

    if (!ce) {
        ce = {!! $ctx->ceVarName !!};
    }

    object_init_ex(return_value, ce);
    if (UNEXPECTED(Z_TYPE_P(return_value) != IS_OBJECT)) {
        if (!EG(exception)) {
            zend_throw_error(NULL, "Failed to instantiate PHP wrapper for {!! addslashes($ctx->phpClassName) !!}");
        }
        return;
    }
    {!! $ctx->objectStructName !!} *intern = {!! $ctx->zMacro !!}(return_value);
    intern->native_ptr = native;
    qt_track_native_instance(intern->native_ptr);
@if($ctx->isQObjectDerived)
    qt_runtime_try_hook_about_to_quit();
@endif
    intern->prevent_destroy = prevent_destroy;
@if($ctx->tracksGeneratedNativeSubclass)
    intern->native_is_generated_subclass = false;
@if($ctx->requiresVirtualTrampoline)
    intern->native_is_virtual_trampoline = false;
@endif
@endif
}

