/* connectPropertyNotify */
ZEND_METHOD({!! $ctx->zendClassSymbol !!}, connectPropertyNotify)
{
    zend_string *name;
    zval *callback;

    ZEND_PARSE_PARAMETERS_START(2, 2)
        Z_PARAM_STR(name)
        Z_PARAM_ZVAL(callback)
    ZEND_PARSE_PARAMETERS_END();

    {!! $ctx->objectStructName !!} *intern = {!! $ctx->zMacro !!}(ZEND_THIS);
    QObject *_qt_obj = intern->native_ptr != NULL ? static_cast<QObject *>(intern->native_ptr) : NULL;
    if (_qt_obj == NULL) {
        zend_throw_error(NULL, "{!! addslashes($ctx->phpClassName) !!} native instance is not initialized");
        RETURN_THROWS();
    }

    if (qt_qobject_meta_property_index(_qt_obj, name) < 0) {
        if (qt_qobject_has_dynamic_property(_qt_obj, name)) {
            zend_value_error("Dynamic property %s does not provide a NOTIFY signal.", ZSTR_VAL(name));
        } else {
            zend_value_error("Unknown property %s.", ZSTR_VAL(name));
        }
        RETURN_THROWS();
    }

    const int _qt_property_index = qt_qobject_meta_property_index(_qt_obj, name);
    auto _qt_property = _qt_obj->metaObject()->property(_qt_property_index);
    auto _qt_notify = _qt_property.notifySignal();
    if (!_qt_notify.isValid()) {
        zend_value_error("Property %s does not provide a NOTIFY signal.", ZSTR_VAL(name));
        RETURN_THROWS();
    }

    auto _qt_callback = qt_signal_callback_create(_qt_obj, callback);
    if (_qt_callback == nullptr) {
        RETURN_THROWS();
    }

    struct _qt_property_notify_handler_t {
        std::shared_ptr<qt_signal_callback_t> callback;

        void operator()() const
        {
            auto _qt_callback_copy = callback;
            qt_signal_dispatch([_qt_callback_copy]() mutable {
                qt_signal_callback_invoke(_qt_callback_copy, 0, nullptr);
            });
        }
    };

@if($ctx->supportsRuntimeNotifyFunctorConnect)
    QMetaObject::Connection _qt_connection = QMetaObject::connect(
        _qt_obj,
        _qt_notify,
        _qt_obj,
        _qt_property_notify_handler_t{_qt_callback}
    );

    qt_qmetaobjectconnection_wrap(return_value, _qt_connection);
@else
    QSignalMapper *_qt_mapper = new QSignalMapper(_qt_obj);
    _qt_mapper->setMapping(_qt_obj, _qt_obj);

    const QMetaObject &_qt_mapper_meta = QSignalMapper::staticMetaObject;
    const int _qt_map_index = _qt_mapper_meta.indexOfSlot("map()");
    const int _qt_mapped_index = _qt_mapper_meta.indexOfSignal("mappedObject(QObject*)");
    if (_qt_map_index < 0 || _qt_mapped_index < 0) {
        delete _qt_mapper;
        zend_throw_error(NULL, "QSignalMapper bridge methods are unavailable for connectPropertyNotify().");
        RETURN_THROWS();
    }

    const QMetaMethod _qt_map_method = _qt_mapper_meta.method(_qt_map_index);
    QMetaObject::Connection _qt_connection = QObject::connect(
        _qt_obj,
        _qt_notify,
        _qt_mapper,
        _qt_map_method
    );
    if (!_qt_connection) {
        delete _qt_mapper;
        zend_throw_error(NULL, "Failed to connect property notify bridge for property %s.", ZSTR_VAL(name));
        RETURN_THROWS();
    }

    QMetaObject::Connection _qt_bridge_connection = QObject::connect(
        _qt_mapper,
        qOverload<QObject *>(&QSignalMapper::mappedObject),
        _qt_obj,
        [_qt_handler = _qt_property_notify_handler_t{_qt_callback}](QObject *) {
            _qt_handler();
        }
    );
    if (!_qt_bridge_connection) {
        QObject::disconnect(_qt_connection);
        delete _qt_mapper;
        zend_throw_error(NULL, "Failed to connect property notify callback bridge for property %s.", ZSTR_VAL(name));
        RETURN_THROWS();
    }

    qt_qmetaobjectconnection_wrap_aux(
        return_value,
        _qt_connection,
        qt_qmetaobjectconnection_create_bridge_aux(_qt_mapper, _qt_bridge_connection)
    );
@endif
}
